import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"Project Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1792461198000}'),s={name:"guide/overview.md"};function r(i,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Experimental Project</p><p>AgentPay is in active development and has <strong>not</strong> undergone an independent third-party security audit. It is intended for testnet and sandbox environments only. Do not connect it to production mainnet funds.</p></div><h2 id="what-is-agentpay" tabindex="-1">What is AgentPay? <a class="header-anchor" href="#what-is-agentpay" aria-label="Permalink to &quot;What is AgentPay?&quot;">​</a></h2><p><strong>AgentPay</strong> is an open-source <strong>financial firewall and autonomous payment gateway</strong> for AI Agents.</p><p>As LLM agents call external tools, APIs and data sources (Tool Calling, MCP, LangChain, CrewAI…), more and more of those resources are paid. The x402 protocol answers the question <em>&quot;how does an agent pay for an HTTP resource?&quot;</em> AgentPay answers the harder question that comes right after it:</p><blockquote><p><strong>Should this agent be allowed to pay, how much, to whom, and what happens when something goes wrong?</strong></p></blockquote><p>The guiding principle is simple: <strong>an LLM may <em>propose</em> a payment, but it can never <em>authorize</em> one.</strong> Every payment passes through deterministic, non-LLM code that enforces budgets and policies before any money moves.</p><h3 id="who-is-it-for" tabindex="-1">Who is it for? <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who is it for?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>You are…</th><th>AgentPay gives you…</th></tr></thead><tbody><tr><td><strong>An agent developer</strong> (buyer)</td><td>A drop-in Python client that handles <code>HTTP 402</code>, enforces local spending limits, and never lets the model touch a private key.</td></tr><tr><td><strong>An API / tool provider</strong> (seller)</td><td>A reverse-proxy gateway that turns any existing HTTP API into a paid API with a YAML or console-managed route — no changes to your upstream code.</td></tr><tr><td><strong>A platform / enterprise team</strong></td><td>Multi-tenant isolation, RBAC, per-agent API keys, a virtual wallet, an audit timeline and a one-click kill switch.</td></tr></tbody></table><hr><h2 id="the-problems-it-solves" tabindex="-1">The Problems It Solves <a class="header-anchor" href="#the-problems-it-solves" aria-label="Permalink to &quot;The Problems It Solves&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>What goes wrong</th><th>How AgentPay mitigates it</th></tr></thead><tbody><tr><td><strong>Runaway loops</strong></td><td>A buggy tool-calling loop re-pays the same API hundreds of times in seconds.</td><td>Rolling 24h budget, per-request cap, request-rate limits and a loop-detecting <strong>circuit breaker</strong>.</td></tr><tr><td><strong>Prompt injection &amp; hallucination</strong></td><td>A poisoned prompt convinces the agent to pay an attacker or an inflated price.</td><td>Payee / network / asset <strong>whitelists</strong> and a hard <code>max_per_tx</code> cap, evaluated outside the model.</td></tr><tr><td><strong>Key exposure</strong></td><td>Private keys or master secrets leak through the prompt context.</td><td>Wallet path: the agent holds only a revocable API key. On-chain path: the key stays in the buyer&#39;s local signer / KMS and is never sent to the gateway.</td></tr><tr><td><strong>Double charging</strong></td><td>A timeout is mistaken for a failure, the request is retried, and the buyer pays twice.</td><td>A <strong>three-state model</strong> (intent / settlement / fulfillment), idempotency keys, and a rule that <em>timeout ≠ failure</em>.</td></tr><tr><td><strong>Budget races</strong></td><td>Two concurrent requests both see &quot;enough budget&quot; and together overspend.</td><td><strong>Atomic reservation</strong> (<code>reserve → commit / release</code>) and row-level locking (<code>SELECT … FOR UPDATE</code>).</td></tr><tr><td><strong>Cross-tenant leakage</strong></td><td>One customer reads or modifies another customer&#39;s routes, keys or funds.</td><td>Tenant-scoped data model, server-side RBAC and dedicated isolation / penetration tests.</td></tr><tr><td><strong>Rogue agents</strong></td><td>An agent misbehaves in production.</td><td><strong>Kill switch</strong>: suspend an agent or revoke its API keys and the gateway blocks new requests within seconds.</td></tr></tbody></table><hr><h2 id="how-a-payment-works" tabindex="-1">How a Payment Works <a class="header-anchor" href="#how-a-payment-works" aria-label="Permalink to &quot;How a Payment Works&quot;">​</a></h2><p>AgentPay supports two payment paths. The gateway selects one deterministically from the credentials on the request.</p><h3 id="path-a-—-virtual-wallet-api-key" tabindex="-1">Path A — Virtual Wallet (API key) <a class="header-anchor" href="#path-a-—-virtual-wallet-api-key" aria-label="Permalink to &quot;Path A — Virtual Wallet (API key)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent ── HTTP + Authorization: Bearer apk_live_… ──▶ Gateway</span></span>
<span class="line"><span>   1. Authenticate key  → resolve tenant, project and agent</span></span>
<span class="line"><span>   2. Policy check      → per-tx cap, budget, rate limit, route allow-list</span></span>
<span class="line"><span>   3. HOLD              → freeze the price in the tenant wallet (row-locked)</span></span>
<span class="line"><span>   4. Forward to upstream (upstream credentials injected by the gateway)</span></span>
<span class="line"><span>   5a. 2xx  → CAPTURE   → append ledger entry, return 200</span></span>
<span class="line"><span>   5b. 4xx  → RELEASE   → unfreeze, nothing charged</span></span>
<span class="line"><span>   5c. 5xx / timeout → keep HELD, mark needs_review (never auto-charge, never auto-release)</span></span></code></pre></div><h3 id="path-b-—-on-chain-x402-eip-3009" tabindex="-1">Path B — On-Chain x402 (EIP-3009) <a class="header-anchor" href="#path-b-—-on-chain-x402-eip-3009" aria-label="Permalink to &quot;Path B — On-Chain x402 (EIP-3009)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent ── GET /resource ──▶ Gateway</span></span>
<span class="line"><span>Agent ◀── 402 + PAYMENT-REQUIRED (price, payee, asset, network, expiry) ──</span></span>
<span class="line"><span>   1. Client parses the challenge</span></span>
<span class="line"><span>   2. Local policy engine: evaluate + atomically RESERVE budget</span></span>
<span class="line"><span>   3. Local signer: sign an EIP-712 / EIP-3009 authorization</span></span>
<span class="line"><span>   4. Replay request with PAYMENT-SIGNATURE</span></span>
<span class="line"><span>   5. Gateway verifies signature, nonce and price → forwards upstream</span></span>
<span class="line"><span>   6. Facilitator settles on-chain (gas sponsored, buyer needs only USDC)</span></span>
<span class="line"><span>   7. Buyer commits (or, after the authorization expires unspent, releases) the reservation</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">No silent fallback</p><p>If a wallet-path request has insufficient balance, the gateway returns <code>402 ERR_WALLET_INSUFFICIENT_BALANCE</code>. It <strong>never</strong> quietly switches to an on-chain charge. Moving to the on-chain path must be an explicit, new request signed by the buyer.</p></div><hr><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────┐        ┌───────────────────────────────┐        ┌────────────────────┐</span></span>
<span class="line"><span>│       AI Agent       │        │        AgentPay Gateway       │        │  Upstream Service  │</span></span>
<span class="line"><span>│ LangChain / CrewAI / │ ─────▶ │  Auth · Policy · x402 · Proxy │ ─────▶ │  (your existing    │</span></span>
<span class="line"><span>│  custom + SDK client │        │  Wallet Hold/Capture/Release  │        │   HTTP API)        │</span></span>
<span class="line"><span>└──────────┬───────────┘        └───────┬───────────────┬───────┘        └────────────────────┘</span></span>
<span class="line"><span>           │                            │               │</span></span>
<span class="line"><span>   Local policy engine /         PostgreSQL 15+     Facilitator ──▶ EVM chain</span></span>
<span class="line"><span>   local signer (on-chain)     (ledger, config,    (verify &amp; settle, Arbitrum Sepolia)</span></span>
<span class="line"><span>                                 audit events)</span></span>
<span class="line"><span>                                        ▲</span></span>
<span class="line"><span>                              Management Console (Vue 3)</span></span>
<span class="line"><span>                              routes · policies · wallet · agents · audit</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><strong>Python SDK</strong> (<code>agentpay</code>)</td><td>Transparent <code>httpx</code> interceptor (sync + async): detects <code>402</code>, runs the local firewall, signs, replays, commits or releases. Includes a LangChain paid-tool wrapper.</td></tr><tr><td><strong>Financial Firewall / Policy Engine</strong></td><td>Per-tx cap, rolling 24h budget, lifetime limit, payee / domain / network whitelists, rate limit, circuit breaker. SQLite-backed atomic reservation on the buyer side.</td></tr><tr><td><strong>Gateway</strong> (<code>gateway-go</code>)</td><td>Go reverse proxy: route matching, 402 challenge generation, signature verification, header sanitization, upstream credential isolation, idempotency, recovery, agent-level policy and kill switch. A Python reference gateway ships for the v0.1.0 baseline.</td></tr><tr><td><strong>Virtual Wallet &amp; Ledger</strong></td><td>One wallet per tenant; append-only ledger; Hold / Capture / Release; reconciliation.</td></tr><tr><td><strong>Facilitator</strong></td><td>Verifies authorizations and submits gas-sponsored <code>transferWithAuthorization</code> transactions. A mock Facilitator is provided for local runs.</td></tr><tr><td><strong>Management Console</strong></td><td>Routes &amp; upstream auth, config draft → validate → publish → rollback, wallet, agents &amp; audit timeline.</td></tr><tr><td><strong>PostgreSQL</strong></td><td>System of record for tenants, projects, routes, policies, ledger, payments and audit events.</td></tr></tbody></table><hr><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="tenancy-and-identity" tabindex="-1">Tenancy and identity <a class="header-anchor" href="#tenancy-and-identity" aria-label="Permalink to &quot;Tenancy and identity&quot;">​</a></h3><p><code>Tenant → Project → Agent → API Key</code>. Every project belongs to exactly one tenant, every API key belongs to exactly one agent, and the <strong><code>agent_id</code> is always derived from the credential</strong> — client-supplied headers such as <code>X-Agent-ID</code> are stripped and never trusted. Optional self-reported metadata (<code>X-Session-ID</code>, <code>X-Task-ID</code>, <code>X-Tool-Name</code>) is used only to group the audit timeline; it never affects authentication, billing or policy.</p><h3 id="the-three-state-model" tabindex="-1">The three-state model <a class="header-anchor" href="#the-three-state-model" aria-label="Permalink to &quot;The three-state model&quot;">​</a></h3><p>A single &quot;payment succeeded / failed&quot; flag cannot describe reality. AgentPay tracks three orthogonal state lines:</p><table tabindex="0"><thead><tr><th>Object</th><th>Question it answers</th><th>Example states</th></tr></thead><tbody><tr><td><strong>PaymentIntent</strong></td><td>Where is this request in its overall lifecycle?</td><td><code>created</code>, <code>challenged</code>, <code>authorized</code>, <code>completed</code>, <code>rejected</code>, <code>expired</code>, <code>failed</code>, <code>needs_review</code></td></tr><tr><td><strong>Settlement</strong></td><td>Did the money actually move?</td><td><code>not_started</code>, <code>held</code>, <code>submitted</code>, <code>pending</code>, <code>confirmed</code>, <code>released</code>, <code>failed</code>, <code>unknown</code></td></tr><tr><td><strong>Fulfillment</strong></td><td>Did the upstream actually deliver?</td><td><code>not_started</code>, <code>in_progress</code>, <code>succeeded</code>, <code>failed</code>, <code>unknown</code></td></tr></tbody></table><p><code>unknown</code> is a first-class state. An ambiguous result is never treated as success <strong>or</strong> failure, and is resolved only by querying, never by blind retry. See the <a href="/docs/specs/state-machine">State Machine spec</a>.</p><h3 id="idempotency" tabindex="-1">Idempotency <a class="header-anchor" href="#idempotency" aria-label="Permalink to &quot;Idempotency&quot;">​</a></h3><p>Clients send an <code>Idempotency-Key</code>. The same key plus the same request fingerprint replays the stored result (<code>X-Cache: HIT</code>) at <strong>zero additional cost</strong>; the same key with a different payload returns <code>409 ERR_IDEMPOTENCY_CONFLICT</code>. After an upstream 5xx, retrying with the same key reuses the original hold instead of charging again.</p><h3 id="versioned-configuration" tabindex="-1">Versioned configuration <a class="header-anchor" href="#versioned-configuration" aria-label="Permalink to &quot;Versioned configuration&quot;">​</a></h3><p>Route and policy changes are edited as drafts, validated, then published as an <strong>immutable, hash-fingerprinted snapshot</strong>. Gateways swap to the new snapshot atomically with no downtime, every request records the config version that served it, and a rollback is a single pointer swap. If the control plane goes down, gateways keep serving from their last good snapshot and fail closed on anything they cannot verify.</p><hr><h2 id="safety-invariants" tabindex="-1">Safety Invariants <a class="header-anchor" href="#safety-invariants" aria-label="Permalink to &quot;Safety Invariants&quot;">​</a></h2><p>These rules are not tunable settings; they are design constraints enforced in code, in the database and in tests.</p><ol><li><strong>Integer money only.</strong> All amounts are integers in the smallest unit (USDC = 6 decimals). No floats anywhere, and database columns carry integer / non-negative <code>CHECK</code> constraints.</li><li><strong>Fail closed.</strong> Lock timeout, parse error, verification failure or any unhandled exception ⇒ reject.</li><li><strong>Sign only after approval.</strong> The signer is invoked only for a reservation the policy engine has already approved.</li><li><strong>A signature in flight is never &quot;un-spent&quot; by a timeout.</strong> Budget is released only after the authorization has expired <em>and</em> it is confirmed unspent on-chain.</li><li><strong>Unknown never auto-resolves.</strong> Unknown fulfillment keeps wallet funds held and escalates to <code>needs_review</code>.</li><li><strong>Append-only ledger.</strong> Ledger entries and audit events are never updated or deleted; corrections are new reversal / adjustment entries.</li><li><strong>The model has no financial authority.</strong> The policy engine is not an LLM tool, and the LLM cannot read or modify it.</li></ol><hr><h2 id="deployment-topologies" tabindex="-1">Deployment Topologies <a class="header-anchor" href="#deployment-topologies" aria-label="Permalink to &quot;Deployment Topologies&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Local embedded sandbox</th><th>Cloud-native distributed</th></tr></thead><tbody><tr><td><strong>Use it for</strong></td><td>Development, CI, demos (<code>make demo</code>)</td><td>Real testnet integrations</td></tr><tr><td><strong>Transport</strong></td><td>In-memory ASGI transport (no sockets)</td><td>HTTPS between independent buyer and seller domains</td></tr><tr><td><strong>Chain</strong></td><td>Local mock EVM RPC</td><td>Arbitrum Sepolia (<code>eip155:421614</code>)</td></tr><tr><td><strong>Keys</strong></td><td>Test key</td><td>Buyer&#39;s local signer / KMS; never uploaded</td></tr><tr><td><strong>Gas</strong></td><td>Simulated</td><td>Sponsored by the Facilitator; buyer holds only USDC</td></tr></tbody></table><p>See <a href="/docs/guide/deployment">Deployment</a> for details.</p><hr><h2 id="scope-and-known-limitations" tabindex="-1">Scope and Known Limitations <a class="header-anchor" href="#scope-and-known-limitations" aria-label="Permalink to &quot;Scope and Known Limitations&quot;">​</a></h2><p>AgentPay is explicit about what it does <strong>not</strong> do:</p><ul><li><strong>No withdrawals in v1.</strong> The virtual wallet is a closed-loop spending balance; there is no withdrawal and no user-to-user transfer.</li><li><strong>No semantic quality checks.</strong> AgentPay verifies that a paid call was delivered, not that the answer was <em>good</em>. Spending your allowed budget on a useless-but-whitelisted API is out of scope.</li><li><strong>Host compromise is out of scope.</strong> If an attacker has root on the machine running the local signer, they can read the key. HSM / KMS signers are planned.</li><li><strong>In-process tools are not sandboxed.</strong> In embedded mode the SDK shares a process with the agent; a tool with arbitrary code execution could bypass the interceptor. An out-of-process sidecar is planned.</li><li><strong>Single ledger per key.</strong> One private key must map to exactly one local ledger; running several processes with separate ledgers on the same key multiplies the budget.</li><li><strong>Single asset, testnet only.</strong> v1 supports one asset (USDC, EIP-3009 compatible) on testnets.</li></ul><p>Read the full <a href="/docs/specs/">Threat Model</a> for what is and isn&#39;t defended.</p><hr><h2 id="current-status-and-roadmap" tabindex="-1">Current Status and Roadmap <a class="header-anchor" href="#current-status-and-roadmap" aria-label="Permalink to &quot;Current Status and Roadmap&quot;">​</a></h2><p><strong>Available today (v0.1.x)</strong></p><ul><li>Python SDK with <code>httpx</code> interceptor, local firewall (SQLite atomic reservation, circuit breaker), EIP-712 / EIP-3009 signer and LangChain paid-tool wrapper</li><li>Go gateway: reverse proxy, x402 handling, wallet path, idempotency &amp; recovery, agent-level policy, kill switch, audit timeline</li><li>Multi-tenant control plane: tenants, projects, RBAC, agents, API keys, wallet &amp; admin grants, routes &amp; policies</li><li>Management console: routes and upstream auth, config publishing and rollback, wallet, agents, payment audit</li><li>PostgreSQL 15+ schema, Python / Go cross-language conformance vectors</li><li>Arbitrum Sepolia testnet settlement and a one-command <strong>runaway-loop demo</strong></li></ul><p><strong>In progress / next</strong></p><ul><li>Ledger reconciliation (five-way balancing), usage statistics, audit retention &amp; export</li><li>Admin-operation audit and YAML import / export</li><li>Performance benchmarks, clean-environment deployment verification, pilot and release candidate</li></ul><p><strong>Roadmap (2027+)</strong></p><ul><li><strong>Gas model 2 (v0.2.0):</strong> dynamic gas surcharge folded into the USDC amount</li><li><strong>Gas model 3 (v0.3.0):</strong> batched / state-channel settlement for per-token micro-payments</li><li>On-chain and fiat wallet top-ups</li><li>TypeScript / Node.js SDK and Express / Fastify middleware</li><li>Java / Spring Boot starter</li><li>Anomaly detection and alerting (alert-only by default)</li><li>Multi-node distributed gateway clusters, KMS / HSM signers</li></ul><hr><h2 id="where-to-go-next" tabindex="-1">Where to Go Next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to Go Next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to…</th><th>Read</th></tr></thead><tbody><tr><td>Run it in five minutes</td><td><a href="/docs/guide/quickstart">5-Minute Quickstart</a></td></tr><tr><td>Wire an agent up</td><td><a href="/docs/guide/python-sdk">Python SDK</a></td></tr><tr><td>Monetize an API</td><td><a href="/docs/guide/gateway">Gateway Configuration</a></td></tr><tr><td>Set spending limits</td><td><a href="/docs/guide/policy">Policy Configuration</a></td></tr><tr><td>Manage tenants, keys and routes</td><td><a href="/docs/guide/console">Management Console</a></td></tr><tr><td>Understand the wire protocol</td><td><a href="/docs/guide/api-specs">API Specs</a></td></tr><tr><td>Understand the guarantees</td><td><a href="/docs/specs/state-machine">State Machine</a></td></tr><tr><td>Deploy it</td><td><a href="/docs/guide/deployment">Deployment</a></td></tr><tr><td>Contribute</td><td><a href="/docs/contributing/good-first-issues">Good First Issues</a></td></tr></tbody></table>`,60)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
